import{a as e,c as t,i as n,l as r,s as i,t as a}from"./app-B8uz0aqq.js";var o=JSON.parse(`{"path":"/qa/q9-cellappmgr-failure.html","title":"Q9: CellAppMgr 如果宕机了怎么办？有哪些解决方案？","lang":"en-US","frontmatter":{},"filePathRelative":"qa/q9-cellappmgr-failure.md","git":{"createdTime":1773965296000,"updatedTime":1773965296000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),s={name:`q9-cellappmgr-failure.md`};function c(a,o,s,c,l,u){let d=r(`Mermaid`);return t(),n(`div`,null,[o[0]||=e(`<h1 id="q9-cellappmgr-如果宕机了怎么办-有哪些解决方案" tabindex="-1"><a class="header-anchor" href="#q9-cellappmgr-如果宕机了怎么办-有哪些解决方案"><span>Q9: CellAppMgr 如果宕机了怎么办？有哪些解决方案？</span></a></h1><h2 id="问题分析" tabindex="-1"><a class="header-anchor" href="#问题分析"><span>问题分析</span></a></h2><p>CellAppMgr 是 BigWorld/KBEngine 架构中的核心管理组件，负责：</p><ul><li>协调所有 CellApp 的工作</li><li>空间分区负载均衡</li><li>动态调整 Cell 边界</li><li>Entity 跨 CellApp 迁移</li></ul><p>如果 CellAppMgr 宕机会发生什么？如何解决？</p><hr><h2 id="kbengine-的实际情况" tabindex="-1"><a class="header-anchor" href="#kbengine-的实际情况"><span>KBEngine 的实际情况</span></a></h2><h3 id="官方确认" tabindex="-1"><a class="header-anchor" href="#官方确认"><span>官方确认</span></a></h3><p>根据 <a href="https://www.kbelab.com/manual/engine-overview.html" target="_blank" rel="noopener noreferrer">KBEngine Lab 官方文档</a>：</p><blockquote><p>&quot;一个KBE架构中，只会出现一个 <strong>CellappMgr</strong>&quot;</p></blockquote><p><strong>KBEngine 原生设计是单 CellAppMgr，没有内置高可用方案。</strong></p><h3 id="宕机影响" tabindex="-1"><a class="header-anchor" href="#宕机影响"><span>宕机影响</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────┐</span>
<span class="line">│                      CellAppMgr ❌                          │</span>
<span class="line">│                   如果这个进程挂了：                          │</span>
<span class="line">│  - 无法创建新 Cell                                           │</span>
<span class="line">│  - 无法进行负载均衡                                           │</span>
<span class="line">│  - 无法调整 Cell 边界                                         │</span>
<span class="line">│  - 无法处理 Entity 跨 CellApp 迁移                           │</span>
<span class="line">│  - 现有 Cell 仍可运行，但扩展能力丧失                          │</span>
<span class="line">└─────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>功能</th><th>宕机后状态</th></tr></thead><tbody><tr><td>现有 CellApp</td><td>✅ 继续运行</td></tr><tr><td>现有玩家</td><td>✅ 不受影响</td></tr><tr><td>新玩家登录</td><td>✅ 可以进入</td></tr><tr><td>负载均衡</td><td>❌ 停止</td></tr><tr><td>动态扩容</td><td>❌ 停止</td></tr><tr><td>边界调整</td><td>❌ 停止</td></tr></tbody></table><hr><h2 id="解决方案" tabindex="-1"><a class="header-anchor" href="#解决方案"><span>解决方案</span></a></h2><h3 id="方案-1-进程监控-自动重启-最简单" tabindex="-1"><a class="header-anchor" href="#方案-1-进程监控-自动重启-最简单"><span>方案 1: 进程监控 + 自动重启（最简单）</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token comment"># Supervisor 配置</span></span>
<span class="line"><span class="token punctuation">[</span>program:cellappmgr<span class="token punctuation">]</span></span>
<span class="line"><span class="token assign-left variable">command</span><span class="token operator">=</span>/usr/local/kbe/bin/cellappmgr</span>
<span class="line"><span class="token assign-left variable">directory</span><span class="token operator">=</span>/usr/local/kbe/</span>
<span class="line"><span class="token assign-left variable">user</span><span class="token operator">=</span>kbe</span>
<span class="line"><span class="token assign-left variable">autostart</span><span class="token operator">=</span>true</span>
<span class="line"><span class="token assign-left variable">autorestart</span><span class="token operator">=</span>true</span>
<span class="line"><span class="token assign-left variable">startsecs</span><span class="token operator">=</span><span class="token number">10</span></span>
<span class="line"><span class="token assign-left variable">startretries</span><span class="token operator">=</span><span class="token number">3</span></span>
<span class="line"><span class="token assign-left variable">stopwaitsecs</span><span class="token operator">=</span><span class="token number">60</span></span>
<span class="line"><span class="token assign-left variable">redirect_stderr</span><span class="token operator">=</span>true</span>
<span class="line"><span class="token assign-left variable">stdout_logfile</span><span class="token operator">=</span>/var/log/kbe/cellappmgr.log</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>工作流程</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">CellAppMgr 宕机</span>
<span class="line">       ↓</span>
<span class="line">Supervisor 检测到进程退出</span>
<span class="line">       ↓</span>
<span class="line">自动重启 CellAppMgr</span>
<span class="line">       ↓</span>
<span class="line">CellAppMgr 从持久化数据恢复状态</span>
<span class="line">       ↓</span>
<span class="line">请求所有 CellApp 重新上报状态</span>
<span class="line">       ↓</span>
<span class="line">服务恢复正常</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>恢复时间</strong>：通常 10-30 秒</p><table><thead><tr><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td>实现简单</td><td>恢复期间服务不可用</td></tr><tr><td>无需修改源码</td><td>丢失宕机期间的负载调整</td></tr><tr><td>成熟工具支持</td><td>无法处理机器故障</td></tr></tbody></table><h3 id="方案-2-状态持久化-快速恢复" tabindex="-1"><a class="header-anchor" href="#方案-2-状态持久化-快速恢复"><span>方案 2: 状态持久化 + 快速恢复</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// CellAppMgr 定期持久化状态</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">CellAppMgr</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">saveState</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        StateSnapshot snapshot<span class="token punctuation">;</span></span>
<span class="line">        snapshot<span class="token punctuation">.</span>timestamp <span class="token operator">=</span> <span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        snapshot<span class="token punctuation">.</span>version <span class="token operator">=</span> stateVersion<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 保存所有 Cell 边界</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">&amp;</span> cell <span class="token operator">:</span> cells<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            snapshot<span class="token punctuation">.</span>cells<span class="token punctuation">[</span>cell<span class="token punctuation">.</span>id<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">                cell<span class="token punctuation">.</span>owner<span class="token punctuation">,</span></span>
<span class="line">                cell<span class="token punctuation">.</span>bounds<span class="token punctuation">,</span></span>
<span class="line">                cell<span class="token punctuation">.</span>load</span>
<span class="line">            <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 保存所有 Space 分配</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span><span class="token operator">&amp;</span> space <span class="token operator">:</span> spaces<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            snapshot<span class="token punctuation">.</span>spaces<span class="token punctuation">[</span>space<span class="token punctuation">.</span>id<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">                space<span class="token punctuation">.</span>cellApp<span class="token punctuation">,</span></span>
<span class="line">                space<span class="token punctuation">.</span>bounds</span>
<span class="line">            <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 保存负载均衡状态</span></span>
<span class="line">        snapshot<span class="token punctuation">.</span>balanceState <span class="token operator">=</span> currentBalanceState<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 持久化到数据库/文件</span></span>
<span class="line">        db<span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token string">&quot;cellappmgr_state&quot;</span><span class="token punctuation">,</span> snapshot<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">recover</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 1. 加载最新快照</span></span>
<span class="line">        <span class="token keyword">auto</span> snapshot <span class="token operator">=</span> db<span class="token operator">-&gt;</span><span class="token function">load</span><span class="token punctuation">(</span><span class="token string">&quot;cellappmgr_state&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 2. 恢复状态</span></span>
<span class="line">        cells <span class="token operator">=</span> snapshot<span class="token punctuation">.</span>cells<span class="token punctuation">;</span></span>
<span class="line">        spaces <span class="token operator">=</span> snapshot<span class="token punctuation">.</span>spaces<span class="token punctuation">;</span></span>
<span class="line">        currentBalanceState <span class="token operator">=</span> snapshot<span class="token punctuation">.</span>balanceState<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 3. 请求所有 CellApp 重新上报</span></span>
<span class="line">        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">auto</span> cellapp <span class="token operator">:</span> <span class="token function">discoverCellApps</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            cellapp<span class="token operator">-&gt;</span><span class="token function">reportFullState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 4. 重新计算负载均衡</span></span>
<span class="line">        <span class="token function">rebalance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 定时保存（每5秒）</span></span>
<span class="line"><span class="token keyword">void</span> <span class="token class-name">CellAppMgr</span><span class="token double-colon punctuation">::</span><span class="token function">mainLoop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">while</span> <span class="token punctuation">(</span>running<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 处理负载均衡</span></span>
<span class="line">        <span class="token function">balance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 定期保存状态</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">-</span> lastSaveTime <span class="token operator">&gt;</span> <span class="token number">5</span>s<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">saveState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            lastSaveTime <span class="token operator">=</span> <span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token function">sleep</span><span class="token punctuation">(</span>tickPeriod<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>数据结构</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">cellappmgr_state</span>
<span class="line">├── version: 12345</span>
<span class="line">├── timestamp: 2024-03-19 10:30:00</span>
<span class="line">├── cells</span>
<span class="line">│   ├── cell_1: {owner: &quot;cellapp1&quot;, bounds: [0,0,1000,1000], load: 0.6}</span>
<span class="line">│   ├── cell_2: {owner: &quot;cellapp1&quot;, bounds: [1000,0,2000,1000], load: 0.4}</span>
<span class="line">│   └── ...</span>
<span class="line">├── spaces</span>
<span class="line">│   ├── space_1: {cellapp: &quot;cellapp1&quot;, cell: &quot;cell_1&quot;}</span>
<span class="line">│   └── ...</span>
<span class="line">└── balance_state: {...}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="方案-3-主备模式-需修改源码" tabindex="-1"><a class="header-anchor" href="#方案-3-主备模式-需修改源码"><span>方案 3: 主备模式（需修改源码）</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// CellAppMgr 主备实现</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">CellAppMgr</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">enum</span> <span class="token class-name">Role</span> <span class="token punctuation">{</span> MASTER<span class="token punctuation">,</span> STANDBY <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">    Role role <span class="token operator">=</span> STANDBY<span class="token punctuation">;</span></span>
<span class="line">    CellAppMgr<span class="token operator">*</span> masterAddr <span class="token operator">=</span> <span class="token keyword">nullptr</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 尝试获取 Leader 锁</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">acquireMasterLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">becomeMaster</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">becomeStandby</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">becomeMaster</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        role <span class="token operator">=</span> MASTER<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 持续续租</span></span>
<span class="line">        <span class="token keyword">while</span> <span class="token punctuation">(</span>isMaster<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">renewMasterLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token function">saveState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 主节点定期保存状态</span></span>
<span class="line">            <span class="token function">sleep</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">becomeStandby</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        role <span class="token operator">=</span> STANDBY<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 监控主节点</span></span>
<span class="line">        <span class="token function">watchMaster</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token keyword">this</span><span class="token punctuation">]</span><span class="token punctuation">(</span>MasterEvent event<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>event <span class="token operator">==</span> MASTER_DOWN<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                log<span class="token punctuation">.</span><span class="token function">info</span><span class="token punctuation">(</span><span class="token string">&quot;Master down, becoming master...&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">                <span class="token function">becomeMaster</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">acquireMasterLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 使用分布式锁（Redis/ETCD/ZooKeeper）</span></span>
<span class="line">        <span class="token keyword">return</span> redis<span class="token operator">-&gt;</span><span class="token function">setnx</span><span class="token punctuation">(</span><span class="token string">&quot;cellappmgr:master&quot;</span><span class="token punctuation">,</span> myAddr<span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">renewMasterLock</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 续租</span></span>
<span class="line">        redis<span class="token operator">-&gt;</span><span class="token function">expire</span><span class="token punctuation">(</span><span class="token string">&quot;cellappmgr:master&quot;</span><span class="token punctuation">,</span> <span class="token number">30</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>切换流程</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">┌─────────────────────────────────────────────────────────────┐</span>
<span class="line">│                      CellAppMgr-Master                      │</span>
<span class="line">│                   ❌ 宕机 (心跳超时)                         │</span>
<span class="line">└─────────────────────────────────────────────────────────────┘</span>
<span class="line">                            ↓</span>
<span class="line">┌─────────────────────────────────────────────────────────────┐</span>
<span class="line">│                    CellAppMgr-Standby                       │</span>
<span class="line">│                  检测到 Master 宕机                          │</span>
<span class="line">│                            ↓                                │</span>
<span class="line">│                  尝试获取 Master 锁                          │</span>
<span class="line">│                            ↓                                │</span>
<span class="line">│                  升级为新的 Master                           │</span>
<span class="line">│                            ↓                                │</span>
<span class="line">│                  加载持久化状态                              │</span>
<span class="line">│                            ↓                                │</span>
<span class="line">│                  请求 CellApp 重新上报                       │</span>
<span class="line">└─────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="方案-4-raft-etcd-推荐" tabindex="-1"><a class="header-anchor" href="#方案-4-raft-etcd-推荐"><span>方案 4: RAFT + ETCD（推荐）</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 使用 ETCD 实现 RAFT 一致性</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">DistributedCellAppMgr</span> <span class="token punctuation">{</span></span>
<span class="line">    etcd<span class="token double-colon punctuation">::</span>Client etcd<span class="token punctuation">;</span></span>
<span class="line">    etcd<span class="token double-colon punctuation">::</span>Lease lease<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 1. 参与 RAFT 选举</span></span>
<span class="line">        <span class="token keyword">auto</span> candidate <span class="token operator">=</span> etcd<span class="token punctuation">.</span><span class="token function">candidate</span><span class="token punctuation">(</span><span class="token string">&quot;cellappmgr/leader&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        candidate<span class="token punctuation">.</span><span class="token function">onElected</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token keyword">this</span><span class="token punctuation">]</span><span class="token punctuation">(</span>etcd<span class="token double-colon punctuation">::</span>Leader leader<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">becomeLeader</span><span class="token punctuation">(</span>leader<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        candidate<span class="token punctuation">.</span><span class="token function">onFollower</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token keyword">this</span><span class="token punctuation">]</span><span class="token punctuation">(</span>etcd<span class="token double-colon punctuation">::</span>Leader leader<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token function">becomeFollower</span><span class="token punctuation">(</span>leader<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">becomeLeader</span><span class="token punctuation">(</span>etcd<span class="token double-colon punctuation">::</span>Leader leader<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 作为 Leader 执行负载均衡</span></span>
<span class="line">        <span class="token keyword">while</span> <span class="token punctuation">(</span>leader<span class="token punctuation">.</span><span class="token function">isActive</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 从 ETCD 获取所有 CellApp 状态</span></span>
<span class="line">            <span class="token keyword">auto</span> cellApps <span class="token operator">=</span> etcd<span class="token punctuation">.</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string">&quot;cellapps/&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">            <span class="token comment">// 计算负载均衡</span></span>
<span class="line">            <span class="token keyword">auto</span> plan <span class="token operator">=</span> <span class="token function">calculateBalance</span><span class="token punctuation">(</span>cellApps<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">            <span class="token comment">// 将决策写入 ETCD（同步到所有节点）</span></span>
<span class="line">            etcd<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string">&quot;balance/plan&quot;</span><span class="token punctuation">,</span> plan<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">            <span class="token function">sleep</span><span class="token punctuation">(</span>BALANCE_INTERVAL<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">becomeFollower</span><span class="token punctuation">(</span>etcd<span class="token double-colon punctuation">::</span>Leader leader<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 监听 Leader 的决策</span></span>
<span class="line">        etcd<span class="token punctuation">.</span><span class="token function">watch</span><span class="token punctuation">(</span><span class="token string">&quot;balance/plan&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token keyword">this</span><span class="token punctuation">]</span><span class="token punctuation">(</span>BalancePlan plan<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token comment">// 执行 Leader 的决策</span></span>
<span class="line">            <span class="token function">applyBalancePlan</span><span class="token punctuation">(</span>plan<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// CellApp 状态上报到 ETCD</span></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">CellApp</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">reportLoad</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        etcd<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span>fmt<span class="token double-colon punctuation">::</span><span class="token function">format</span><span class="token punctuation">(</span><span class="token string">&quot;cellapps/{}/load&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                 std<span class="token double-colon punctuation">::</span><span class="token function">to_string</span><span class="token punctuation">(</span>currentLoad<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        etcd<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span>fmt<span class="token double-colon punctuation">::</span><span class="token function">format</span><span class="token punctuation">(</span><span class="token string">&quot;cellapps/{}/entities&quot;</span><span class="token punctuation">,</span> id<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                 <span class="token function">serializeEntities</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>架构图</strong>：</p>`,33),i(d,{code:``}),o[1]||=e(`<hr><h2 id="方案对比" tabindex="-1"><a class="header-anchor" href="#方案对比"><span>方案对比</span></a></h2><table><thead><tr><th>方案</th><th>优点</th><th>缺点</th><th>复杂度</th><th>RTO</th></tr></thead><tbody><tr><td><strong>进程监控</strong></td><td>简单，无需改代码</td><td>恢复慢，机器故障无法处理</td><td>⭐</td><td>10-30s</td></tr><tr><td><strong>状态持久化</strong></td><td>加快恢复</td><td>仍需重启，机器故障无法处理</td><td>⭐⭐</td><td>5-10s</td></tr><tr><td><strong>主备模式</strong></td><td>自动切换</td><td>需改代码，备机闲置</td><td>⭐⭐⭐</td><td>1-5s</td></tr><tr><td><strong>RAFT+ETCD</strong></td><td>完善的高可用</td><td>依赖外部组件</td><td>⭐⭐⭐⭐</td><td>&lt;1s</td></tr></tbody></table><hr><h2 id="apollo-建议方案" tabindex="-1"><a class="header-anchor" href="#apollo-建议方案"><span>Apollo 建议方案</span></a></h2><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// Apollo 采用 RAFT + ETCD 方案</span></span>
<span class="line"><span class="token comment">// 文件: apps/cell-appmgr/include/cellappmgr/distributed_mgr.hpp</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">ApolloCellAppMgr</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 1. 使用 etcd RAFT 进行 Leader 选举</span></span>
<span class="line">    etcd<span class="token double-colon punctuation">::</span>Client etcd<span class="token punctuation">;</span></span>
<span class="line">    etcd<span class="token double-colon punctuation">::</span>Lease lease<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 2. 状态存储在 ETCD</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">storeState</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        etcd<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string">&quot;cellappmgr/state&quot;</span><span class="token punctuation">,</span> <span class="token function">serializeState</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 3. 监听 CellApp 状态变化</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">watchCellApps</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        etcd<span class="token punctuation">.</span><span class="token function">watch</span><span class="token punctuation">(</span><span class="token string">&quot;cellapps/&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token keyword">this</span><span class="token punctuation">]</span><span class="token punctuation">(</span><span class="token keyword">const</span> Event<span class="token operator">&amp;</span> e<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">if</span> <span class="token punctuation">(</span>e<span class="token punctuation">.</span>type <span class="token operator">==</span> PUT<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">                <span class="token function">onCellAppUpdated</span><span class="token punctuation">(</span>e<span class="token punctuation">.</span>key<span class="token punctuation">,</span> e<span class="token punctuation">.</span>value<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">            <span class="token punctuation">}</span></span>
<span class="line">        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token comment">// 4. 计算负载均衡并存储到 ETCD</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">balance</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">auto</span> plan <span class="token operator">=</span> <span class="token function">calculateBalance</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        etcd<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string">&quot;cellappmgr/balance/plan&quot;</span><span class="token punctuation">,</span> plan<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://www.kbelab.com/manual/engine-overview.html" target="_blank" rel="noopener noreferrer">KBEngine Lab - 引擎概览</a></li><li><a href="https://etcd.io/docs/" target="_blank" rel="noopener noreferrer">ETCD 官方文档</a></li><li><a href="https://raft.github.io/" target="_blank" rel="noopener noreferrer">RAFT 一致性算法</a></li></ul>`,9)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};